// Prefer human captions in the spoken language. The auto-generated track tells us which language is spoken.
const res = $input.first().json;
const data = (res.body && res.body.data) || {};
const tracks = data.subtitles || [];
if (!tracks.length) {
  throw new Error('This video has no subtitles. Try a YouTube or Bilibili video with captions.');
}
const isAuto = (t) => /auto-generated/i.test(t.language_name || '');
const auto = tracks.find(isAuto);
const manual = tracks.filter((t) => !isAuto(t));
const pick = manual.find((t) => auto && t.language_tag === auto.language_tag) || auto || manual.find((t) => /^en/.test(t.language_tag)) || manual[0];
const order = ['srt', 'vtt', 'json', 'json3'];
const file = order.map((f) => (pick.urls || []).find((u) => u.format === f)).find(Boolean) || pick.urls[0];

return [{ json: {
  title: data.title || '',
  language: pick.language_name,
  format: file.format,
  subtitle_url: file.url,
  subtitles_cost: Number(res.headers['x-apimodels-cost'] || 0),
} }];

// SRT / VTT -> plain text; Bilibili returns JSON with body[].content.
const meta = $('Pick subtitle track').first().json;
const raw = String($input.first().json.data || '');
let lines = [];
if (raw.trim().startsWith('{')) {
  try {
    const j = JSON.parse(raw);
    lines = (j.body || []).map((x) => x.content).filter(Boolean);
    if (!lines.length && j.events) lines = j.events.map((e) => (e.segs || []).map((s) => s.utf8).join('')).filter(Boolean);
  } catch (e) { /* fall through to text parsing */ }
}
if (!lines.length) {
  lines = raw.split(/\r?\n/)
    .map((l) => l.replace(/<[^>]+>/g, '').trim())
    .filter((l) => l && !/^\d+$/.test(l) && !l.includes('-->') && !/^(WEBVTT|Kind:|Language:)/.test(l));
}
// Auto captions repeat the same line; keep each line once in a row.
const kept = [];
for (const l of lines) if (l !== kept[kept.length - 1]) kept.push(l);
const max = $('Settings').first().json.max_transcript_chars;
const transcript = kept.join(' ').replace(/\s+/g, ' ').trim().slice(0, max);
if (transcript.length < 200) throw new Error('The subtitles are too short to write from.');

return [{ json: { transcript, chars: transcript.length, title: meta.title } }];

