={{ (() => {
  const form = $('Video link form').first().json;
  const lang = form['Output language'] === 'Same as the video' ? 'the same language as the transcript' : form['Output language'];
  const system = [
    'You repurpose video transcripts into written content. Reply with one JSON object and nothing else, with these keys:',
    'blog_title (string);',
    'blog_markdown (string, 600 to 900 words, use ## section headings, no # title, no links you were not given);',
    'x_thread (array of 5 to 8 strings, each under 270 characters, the first one is a hook, at most one hashtag in the last one);',
    'linkedin_post (string, 120 to 220 words, short paragraphs);',
    'newsletter_blurb (string, 60 to 100 words);',
    'cover_prompt (string, an English prompt for a bold, simple 16:9 blog cover about the topic that renders a headline of at most 6 words in large clean letters; give the exact headline in quotes).',
    'Stay faithful to the transcript: do not invent facts, numbers, names or quotes.',
    `Write everything except cover_prompt in ${lang}. Tone: ${form['Tone']}.`
  ].join(' ');
  const user = `Video title: ${$json.title}\nNotes from the user: ${form['Notes for the writer'] || 'none'}\n\nTranscript:\n${$json.transcript}`;
  return JSON.stringify({ model: $('Settings').first().json.writer_model, max_tokens: 6000, messages: [{ role: 'system', content: system }, { role: 'user', content: user }] });
