const res = $input.first().json;
const text = (res.body && res.body.choices && res.body.choices[0].message.content) || '';
const match = text.match(/\{[\s\S]*\}/);
let posts;
try {
  posts = JSON.parse(match ? match[0] : text);
} catch (e) {
  throw new Error('The writing model did not return valid JSON. Run it again or pick another model in Settings.');
}
return [{ json: { ...posts, writer_cost: Number(res.headers['x-apimodels-cost'] || 0) } }];

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const posts = $('Parse posts').first().json;
const sub = $('Pick subtitle track').first().json;
const blog = posts.blog_markdown || '';
// CJK text has no spaces between words, so count characters there.
const cjk = (blog.match(/[\u3040-\u30ff\u3400-\u9fff\uac00-\ud7af]/g) || []).length;
const length = cjk > blog.length / 4 ? `${cjk} characters` : `${blog.split(/\s+/).filter(Boolean).length} words`;

let coverHtml = '';
let coverCost = 0;
if ($('Generate cover').isExecuted) {
  const r = $('Generate cover').first().json;
  const url = r.body && r.body.data && r.body.data[0] && r.body.data[0].url;
  const rec = $('Get cover cost').isExecuted ? $('Get cover cost').first().json : {};
  coverCost = Number((rec.data && rec.data.credits) || 0);
  coverHtml = url
    ? `<h3>Cover</h3><img src="${esc(url)}" alt="Cover image"><p><a class="btn" href="${esc(url)}" target="_blank" rel="noopener">Open full size</a></p>`
    : `<h3>Cover</h3><p class="meta">The cover could not be made: ${esc((r.error && r.error.message) || 'no image returned')}</p>`;
}

const box = (label, text, rows) => `<h3>${label}</h3><textarea readonly rows="${rows}">${esc(text)}</textarea>`;
const thread = (posts.x_thread || []).map((t, i) => `<li><span class="meta">${i + 1}/${posts.x_thread.length} · ${String(t).length} chars</span><br>${esc(t)}</li>`).join('');
const total = sub.subtitles_cost + posts.writer_cost + coverCost;

const html = `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<style>body{font-family:system-ui,-apple-system,Segoe UI,sans-serif;background:#f5f5f4;color:#1c1917;margin:0;padding:32px 16px}
.card{max-width:820px;margin:0 auto;background:#fff;border:1px solid #e7e5e4;border-radius:16px;padding:24px}
h2{margin-top:0}h3{margin:28px 0 8px}img{max-width:100%;border-radius:12px;border:1px solid #e7e5e4}
textarea{width:100%;box-sizing:border-box;font:14px/1.5 ui-monospace,Menlo,monospace;border:1px solid #d6d3d1;border-radius:10px;padding:10px}
ol{padding-left:0;list-style:none}li{border:1px solid #e7e5e4;border-radius:10px;padding:10px;margin:8px 0}
.meta{color:#78716c;font-size:13px}.btn{display:inline-block;padding:9px 16px;border-radius:10px;background:#1c1917;color:#fff;text-decoration:none}</style></head>
<body><div class="card">
<h2>${esc(posts.blog_title || sub.title)}</h2>
<p class="meta">From "${esc(sub.title)}" · ${esc(sub.language)} subtitles · ${length} · charged $${total.toFixed(4)} (subtitles $${sub.subtitles_cost}, writing $${posts.writer_cost}${coverCost ? `, cover $${coverCost}` : ''})</p>
${coverHtml}
${box('Blog post (Markdown)', posts.blog_markdown, 18)}
<h3>X thread</h3><ol>${thread}</ol>
${box('LinkedIn post', posts.linkedin_post, 9)}
${box('Newsletter blurb', posts.newsletter_blurb, 5)}
<p><a class="btn" href="/form/video-to-posts">Do another video</a></p>
</div></body></html>`;

return [{ json: { html } }];

